export type RunStatus = "queued" | "leased" | "preparing" | "running" | "awaiting_gate" | "succeeded" | "failed" | "timed_out" | "cancelled" | "errored";

/**
 * Response of `POST …/runs/{run}/cancel` (a terminal run is a no-op).
 */
export type RunStatusView = { status: RunStatus, };

/**
 * What a run is about. Each `RunKind` has exactly one subject shape.
 */
export type RunSubject = { "type": "repo_version", "data": RepoVersionKey } | { "type": "ticket", "data": TicketId } | { "type": "cause", "data": CauseId } | { "type": "run", "data": RunId };

/**
 * A run without its result, for lists.
 */
export type RunSummary = { id: RunId, kind: RunKind, status: RunStatus, subject: RunSubject, harness: HarnessKind | null, attempt: number, parent: RunId | null, usage: Usage, budget: Budget, error: RunError | null, created_at: string, started_at: string | null, finished_at: string | null, };

export type RunnerId = string;

/**
 * The runner holding a run and until when.
 */
export type RunnerLease = { runner_id: RunnerId, until: string, };

/**
 * `PUT …/repos/{repo}/recipe`: save a Draft (parse, normalize, hash, secret scan).
 */
export type SaveRecipeRequest = { toml: string, };

export type SavedRecipe = { recipe: Recipe, report: RecipeReport, };

/**
 * One org of the session user: `{org, name, role}`.
 */
export type SessionMembership = { 
/**
 * Immutable slug, used in every `/api/v1/orgs/{org}` path.
 */
org: string, name: string, role: MemberRole, };

/**
 * `GET /api/v1/session`.
 */
export type SessionView = { user: User, memberships: Array<SessionMembership>, 
/**
 * Sent back as `X-CSRF-Token` on every mutation; held in memory only.
 */
csrf_token: string, 
/**
 * Enabled feature flags (e.g. `google_login`).
 */
features: Array<string>, };

/**
 * `PUT …/repos/{repo}/deployments/{environment}`: manual mapping. Response: `Deployment`.
 */
export type SetDeploymentRequest = { sha: CommitSha, };

/**
 * `PUT …/settings/model/key` (Owner): validated upstream before it is stored. Response:
 * `ModelKeyMeta`. `Debug` never prints the key.
 */
export type SetModelKeyRequest = { api_key: string, };

/**
 * `PUT …/members/{user}` (Owner). Response: `MemberView`.
 */
export type SetRoleRequest = { role: MemberRole, };

/**
 * `PUT …/tickets/{ticket}/target`: user override (`TargetOrigin::Override`). Response:
 * `TicketTarget`.
 */
export type SetTargetRequest = { repo_id: RepoId, sha: CommitSha, };

/**
 * `POST …/artifacts/{artifact}/share` (`Trace` only): a 10-minute capability URL for the trace
 * origin.
 */
export type ShareLink = { 
/**
 * `{trace_url}/trace/index.html?trace=…`, opened in a new tab.
 */
url: string, expires_at: string, };

export type SignatureKind = "assertion_text" | "http_status" | "error_string" | "exit_code";

export type SlackThreadRef = { team: string, channel: string, ts: string, };

/**
 * `POST …/causes/{cause}/diagnose` and `POST …/causes/{cause}/fix`: optional harness override of
 * the org default. Response: `RunStarted`.
 */
export type StartHarnessRunRequest = { harness?: HarnessKind, };

/**
 * `POST …/repos/{repo}/learn` (onboarding wizard). Response: `RunStarted`.
 */
export type StartLearnRequest = { 
/**
 * Default: the default-branch head version.
 */
sha?: CommitSha, harness?: HarnessKind, };

/**
 * `POST …/runs/{run}/steer` (status `Running` only; text ≤ [`SteerRequest::MAX_TEXT_BYTES`]).
 */
export type SteerRequest = { text: string, };

/**
 * Where a ticket's target sha came from (intake.md). Decides stickiness on re-ingest.
 */
export type TargetOrigin = { "type": "override" } | { "type": "directive" } | { "type": "deployment", environment: string, } | { "type": "default_head" };

export type Ticket = TicketData;

/**
 * Fields of a ticket (read through `Ticket`'s `Deref`).
 */
export type TicketData = { id: TicketId, org_id: OrgId, source: TicketSource, title: string, body: string, content_hash: ContentHash, slack_thread: SlackThreadRef | null, customer: CustomerId | null, target: TicketTarget | null, error_strings: Array<string>, status: TicketStatus, 
/**
 * Content hash the current triage consumed (written when triage starts).
 */
triaged_hash: ContentHash | null, 
/**
 * Fencing token: only this triage run may change the ticket's triage outcome.
 */
triage_run: RunId | null, created_at: string, updated_at: string, };

/**
 * `GET …/tickets/{ticket}`.
 */
export type TicketDetail = { 
/**
 * Content, status, Linear source (identifier + URL) and Slack thread.
 */
ticket: Ticket, assumed: boolean, 
/**
 * Repo of the target, for GitHub permalinks `blob/{sha}/{path}#L{a}-L{b}`.
 */
repo: Repo | null, customer: Customer | null, 
/**
 * Ranked causes of the current triage first, superseded ones after (`superseded_at` set).
 */
causes: Array<Cause>, runs: Array<RunSummary>, pull_requests: Array<FixPullRequest>, resolution: Resolution | null, };

export type TicketId = string;

/**
 * `GET …/tickets?status=&repo=&customer=&q=&cursor=&limit=`. Response: `Paged<TicketSummary>`.
 */
export type TicketListQuery = { status?: TicketStatus, repo?: RepoId, customer?: CustomerId, 
/**
 * Text filter over identifier, title and body.
 */
q?: string, cursor?: string, limit?: number, };

export type TicketSource = { "type": "linear", issue_id: string, 
/**
 * Human identifier, e.g. `ENG-412`.
 */
identifier: string, url: string, };

export type TicketStatus = "new" | "triaging" | "triaged" | "triage_failed" | "diagnosing" | "diagnosed" | "fixing" | "fix_ready" | "pr_open" | "resolved" | "closed";

/**
 * A row of the tickets page.
 */
export type TicketSummary = { id: TicketId, 
/**
 * Linear identifier, e.g. `ENG-412`.
 */
identifier: string, title: string, status: TicketStatus, target: TicketTarget | null, 
/**
 * The target sha is the default-branch head, not a known deployment.
 */
assumed: boolean, top_cause: TopCause | null, customer: CustomerId | null, updated_at: string, };

/**
 * The commit a ticket is diagnosed at.
 */
export type TicketTarget = { repo_id: RepoId, sha: CommitSha, origin: TargetOrigin, };

/**
 * The best-ranked live cause of a ticket.
 */
export type TopCause = { cause_id: CauseId, title: string, confidence: Confidence, };

/**
 * Result of a Triage run. `causes` are the accepted drafts after the gate, merge and ranking
 * (rank = position + 1), with adjusted line ranges applied.
 */
export type TriageResult = { summary: string, causes: Array<CauseDraft>, missing_info: Array<string>, };

/**
 * Per-org triage policy (triage.md Additions; `org_settings` area `triage`).
 */
export type TriageSettings = { 
/**
 * Triage new and changed tickets without a user request.
 */
auto_triage: boolean, harness: HarnessKind, 
/**
 * `None`: server default triage model.
 */
model: string | null, budget: Budget, max_causes: number, 
/**
 * How long triage waits for preferred layers before running degraded.
 */
layer_wait_ms: number, auto_retriage_per_day: number, ticket_cost_cap_micros: number, };

/**
 * Accumulated usage of one run. `wall` is computed server-side.
 */
export type Usage = { input_tokens: number, output_tokens: number, cost_micros: number, turns: number, wall: number, };

export type UsageGroupBy = "run" | "ticket" | "model";

/**
 * `GET …/usage?from=&to=&group_by=` (Admin): metered cost in `[from, to)`.
 */
export type UsageQuery = { from: string, to: string, group_by: UsageGroupBy, };

export type UsageReport = { from: string, to: string, group_by: UsageGroupBy, 
/**
 * Highest cost first.
 */
rows: Array<UsageRow>, total_cost_micros: number, };

export type UsageRow = { 
/**
 * Run id, ticket id or model id, per `group_by`.
 */
key: string, 
/**
 * Human label (ticket identifier, run kind), if any.
 */
label: string | null, runs: number, input_tokens: number, output_tokens: number, cost_micros: number, };

export type User = { id: UserId, email: string, name: string, };

export type UserId = string;

/**
 * A harness's claim about a diagnosis. Only the repro gate moves a cause to `Reproduced`.
 */
export type Verdict = { "type": "reproduced" } | { "type": "not_reproduced" } | { "type": "inconclusive", reason: string, };

/**
 * One repetition of a Verify run.
 */
export type VerifyAttempt = { index: number, kind: AttemptKind, script_exit: number | null, 
/**
 * Script exited 0 (Shell) or the Playwright run passed.
 */
script_passed: boolean, 
/**
 * Playwright `BrowserStatus`, when the script is a Playwright test.
 */
status: string | null, 
/**
 * Observations with `matcher = Exact`, at most 16, matching candidates first.
 */
observed: Array<FailureSignature>, health_ok: boolean, duration_ms: number, };

export type VerifyOutcome = { "type": "completed" } | { "type": "boot_failed", reason: string, } | { "type": "patch_rejected", reason: string, } | { "type": "errored", reason: string, };

/**
 * `POST …/repos/{repo}/recipe/verify`: Boot gate Verify run. Response: `RunStarted`.
 */
export type VerifyRecipeRequest = { hash: RecipeHash, 
/**
 * Default: the default-branch head version.
 */
sha?: CommitSha, };

export type VerifyResult = { outcome: VerifyOutcome, 
/**
 * First candidate of the last attempt (display only).
 */
observed: FailureSignature | null, attempts: Array<VerifyAttempt>, artifacts: Array<ArtifactId>, fix_checks: FixChecks | null, 
/**
 * Rebase flow: the patch re-diffed against the new base, used for every later check.
 */
rebased_patch: ArtifactId | null, };

/**
 * Why a commit is indexed. Drives priority and retention (knowledge.md).
 */
export type VersionReason = { "type": "default_head" } | { "type": "release", "data": string } | { "type": "deployed", "data": string } | { "type": "on_demand", "data": TicketId };

/**
 * An indexed commit and the state of each knowledge layer.
 */
export type VersionView = { sha: CommitSha, reasons: Array<VersionReason>, layers: { [key in Layer]?: LayerState }, created_at: string, };

